287	        serverInLock.lock();
288	        try {
289	            serverIn = new DataInputStream (
290	              new BufferedInputStream (socket.getInputStream ())
291	            );
292	        } finally {
293	            serverInLock.unlock();
294	        }
295	        serverOutLock.lock();
296	        try {
297	            serverOut = new DataOutputStream(
298	              new BufferedOutputStream(socket.getOutputStream(), 2048)
299	            );
300	        } finally {
301	            serverOutLock.unlock();
302	        }
303	        postConnectHook();
304	        usable = true;
305	        cnt[CONNECT]++;
306	        setChanged();
307	        notifyObservers();
308	    }
