    26	
    27	/**
    28	 * Creates a space based on a space URI.
    29	 *
    30	 * <p>A space URI has three parts:
    31	 *  <ul>
    32	 *   <li>scheme
    33	 *   <li>name
    34	 *   <li>optional parameter
    35	 *  </ul>
    36	 * <p>
    37	 * <p>
    38	 *
    39	 * Examples:
    40	 *
    41	 * <pre>
    42	 *   // default unnamed space (tspace:default)
    43	 *   Space sp = SpaceFactory.getSpace ();
    44	 *
    45	 *   // transient space named "test"
    46	 *   Space sp = SpaceFactory.getSpace ("transient:test");
    47	 *
    48	 *   // lspace (Loom-optimized) named "test"
    49	 *   Space sp = SpaceFactory.getSpace ("lspace:test");
    50	 *
    51	 *   // persistent space named "test"
    52	 *   Space sp = SpaceFactory.getSpace ("persistent:test");
    53	 *
    54	 *   // jdbm space named test
    55	 *   Space sp = SpaceFactory.getSpace ("jdbm:test");
    56	 *
    57	 *   // jdbm space named test, storage located in /tmp/test
    58	 *   Space sp = SpaceFactory.getSpace ("jdbm:test:/tmp/test");
    59	 * </pre>
    60	 *
    61	 */
    62	public class SpaceFactory {
    63	    public static final String TSPACE     = "tspace";
    64	    public static final String LSPACE     = "lspace";
    65	    public static final String TRANSIENT  = "transient";
    66	    public static final String PERSISTENT = "persistent";
    67	    public static final String SPACELET   = "spacelet";
    68	    public static final String JDBM       = "jdbm";
    69	    public static final String JE         = "je";
    70	    public static final String DEFAULT    = "default";
    71	    private static ScheduledThreadPoolExecutor gcExecutor = ConcurrentUtil.newScheduledThreadPoolExecutor();
    72	
    73	    /**
    74	     * @return the default TransientSpace
    75	     */
    76	    public static Space getSpace () {
    77	        return getSpace (TSPACE, DEFAULT, null);
    78	    }
    79	
    80	    /**
    81	     * @param spaceUri 
    82	     * @return Space for given URI or null
    83	     */
    84	    public static Space getSpace (String spaceUri) {
    85	        if (spaceUri == null)
    86	            return getSpace ();
    87	
    88	        String scheme = null;
    89	        String name   = null;
    90	        String param  = null;
    91	
    92	        StringTokenizer st = new StringTokenizer (spaceUri, ":");
    93	        int count = st.countTokens();
    94	        if (count == 0) {
    95	            scheme = TSPACE;
    96	            name   = DEFAULT;
    97	        }
    98	        else if (count == 1) {
    99	            scheme = TSPACE;
   100	            name   = st.nextToken ();
   101	        }
   102	        else {
   103	            scheme = st.nextToken ();
   104	            name   = st.nextToken ();
   105	        }
   106	        if (st.hasMoreTokens()) {
   107	            param  = st.nextToken ();
   108	        }
   109	        return getSpace (scheme, name, param);
   110	    }
   111	    public static Space getSpace (String scheme, String name, String param) {
   112	        Space sp = null;
   113	        String uri = normalize (scheme, name, param);
   114	        synchronized (SpaceFactory.class) {
   115	            try {
   116	                sp = (Space) NameRegistrar.get (uri);
   117	            } catch (NameRegistrar.NotFoundException e) {
   118	                if (SPACELET.equals (scheme) || "rspace".equals(scheme))
   119	                    throw new SpaceError (uri + " not found.");
   120	
   121	                sp = createSpace (scheme, name, param);
   122	                NameRegistrar.register (uri, sp);
   123	            }
   124	        }
   125	        if (sp == null) {
   126	            throw new SpaceError ("Invalid space: " + uri);
   127	        }
   128	        return sp;
   129	    }
   130	    public static ScheduledThreadPoolExecutor getGCExecutor() {
   131	        return gcExecutor;
   132	    }
   133	    private static Space createSpace (String scheme, String name, String param)
   134	    {
   135	        Space sp = null;
   136	        if (TSPACE.equals (scheme) || TRANSIENT.equals (scheme)) {
   137	            sp = new TSpace();
   138	        } else if (LSPACE.equals (scheme)) {
   139	            sp = new LSpace();
   140	        } else if (JDBM.equals (scheme) || PERSISTENT.equals (scheme)) {
   141	            if (param != null)
   142	                sp = JDBMSpace.getSpace (name, param);
   143	            else
   144	                sp = JDBMSpace.getSpace (name);
   145	        } else if (JE.equals (scheme)) {
   146	            if (param != null)
   147	                sp = JESpace.getSpace (name, param);
   148	            else
   149	                sp = JESpace.getSpace (name);
   150	        }
   151	        return sp;
   152	    }
   153	    private static String normalize (String scheme, String name, String param) {
   154	        StringBuilder sb = new StringBuilder (scheme);
   155	        sb.append (':');
   156	        sb.append (name);
   157	        if (param != null) {
   158	            sb.append (':');
   159	            sb.append (param);
   160	        }
   161	        return sb.toString();
   162	    }
   163	}
