    55	    @Override
    56	    public void out (K key, V value) {
    57	        var jfr = new SpaceEvent("out", "" + key);
    58	        jfr.begin();
    59	        if (key == null || value == null)
    60	            throw new NullPointerException ("key=" + key + ", value=" + value);
    61	        synchronized(this) {
    62	            List l = getList(key);
    63	            l.add (value);
    64	            if (l.size() == 1)
    65	                this.notifyAll ();
    66	        }
    67	        if (sl != null)
    68	            notifyListeners(key, value);
    69	        jfr.commit();
    70	    }
