   248	    @Override
   249	    public synchronized int size (Object key) {
   250	        var jfr = new SpaceEvent("size", "" + key);
   251	        jfr.begin();
   252	
   253	        int size = 0;
   254	        List l = (List) entries.get (key);
   255	        if (l != null) 
   256	            size = l.size();
   257	        jfr.commit();
   258	        return size;
   259	    }
