   231	     * @throws ConfigurationException If an exception is found trying to create the object.
   232	     */
   233	    @SuppressWarnings("unchecked")
   234	    protected Object getObject(Element childElement)
   235	        throws ConfigurationException
   236	    {
   237	        String type = childElement.getAttributeValue("type","java.lang.String");
   238	        if ("int".equals (type))
   239	            type = "java.lang.Integer";
   240	        else if ("long".equals (type))
