  1092	    private int pauseAndWait(Serializable context, int action) {
  1093	        if (context instanceof Pausable pausable) try {
  1094	            pausedSessions.incrementAndGet();
  1095	            Future<Integer> paused = pausable.pause();
  1096	            long timeout = pausable.getTimeout();
  1097	            timeout = timeout > 0 ? Math.min (timeout, pauseTimeout) : pauseTimeout;
  1098	            try {
  1099	                action = paused.get(timeout, TimeUnit.MILLISECONDS);
  1100	            } catch (InterruptedException | ExecutionException e) {
  1101	                if (context instanceof Context ctx)
  1102	                    ctx.log(e);
  1103	            } catch (TimeoutException e) {
  1104	                action &= (PREPARED ^ 0xFFFF); // turn off 'PREPARED' - we need to abort
  1105	            } finally {
  1106	                pausable.reset();
  1107	            }
  1108	        } finally {
  1109	            pausedSessions.decrementAndGet();
  1110	        }
  1111	        return action;
  1112	    }
