   670	
   671	            if (serverOutLock.tryLock(sendTimeout, TimeUnit.MILLISECONDS)) {
   672	                try  {
   673	                    sendMessageLength(b.length + getHeaderLength(m));
   674	                    sendMessageHeader(m, b.length);
   675	                    sendMessage (b, 0, b.length);
   676	                    sendMessageTrailer(m, b);
   677	                    serverOut.flush ();
   678	                    cnt[TX]++;
   679	                } finally {
   680	                    serverOutLock.unlock();
   681	                }
   682	               incrementMsgOutCounter(m);
   683	            } else {
   684	                disconnect();
   685	            }
   686	            setChanged();
   687	            notifyObservers(m);
   688	            jfr.setDetail(m.toString());
   689	        } catch (VetoException e) {
   690	            //if a filter vets the message it was not added to the event
   691	            evt.addMessage (m);
   692	            evt.addMessage (e);
   693	            jfr.append (e.getMessage());
   694	            throw e;
   695	        } catch (ISOException | IOException e) {
   696	            evt.addMessage (e);
   697	            jfr = new ChannelEvent.SendException(e.getMessage());
   698	            throw e;
   699	        } catch (Exception e) {
   700	            evt.addMessage (e);
   701	            jfr = new ChannelEvent.SendException(e.getMessage());
   702	            throw new IOException ("unexpected exception", e);
   703	        } finally {
   704	            Logger.log (evt);
   705	            jfr.commit();
   706	        }
   707	    }
   708	    /**
   709	     * sends a byte[] over the TCP/IP session
   710	     * @param b the byte array to be sent
   711	     * @exception IOException
   712	     * @exception ISOException
   713	     * @exception ISOFilter.VetoException;
   714	     */
   715	    public void send (byte[] b) throws IOException, ISOException {
   716	        var jfr = new ChannelEvent.Send();
   717	        jfr.begin();
   718	        LogEvent evt = new LogEvent (this, "send");
   719	        try {
   720	            if (!isConnected())
   721	                throw new ISOException ("unconnected ISOChannel");
   722	            serverOutLock.lock();
   723	            try {
   724	                serverOut.write(b);
   725	                serverOut.flush();
   726	            } finally {
   727	                serverOutLock.unlock();
   728	            }
   729	            cnt[TX]++;
   730	            setChanged();
   731	        } catch (Exception e) {
   732	            evt.addMessage (e);
   733	            throw new ISOException ("unexpected exception", e);
   734	        } finally {
   735	            Logger.log (evt);
   736	            jfr.commit();
   737	        }
   738	    }
   739	    /**
   740	     * Sends a high-level keep-alive message (zero length)
   741	     * @throws IOException on exception
   742	     */
   743	    public void sendKeepAlive () throws IOException {
   744	        serverOutLock.lock();
   745	        try {
   746	            sendMessageLength(0);
   747	            serverOut.flush ();
   748	        } finally {
   749	            serverOutLock.unlock();
   750	        }
   751	    }
   752	
   753	    public boolean isExpectKeepAlive() {
   754	        return expectKeepAlive;
   755	    }
   756	
   757	    protected boolean isRejected(byte[] b) {
   758	        // VAP Header support - see VAPChannel
   759	        return false;
   760	    }
   761	    protected boolean shouldIgnore (byte[] b) {
   762	        // VAP Header support - see VAPChannel
   763	        return false;
   764	    }
   765	    /**
   766	     * support old factory method name for backward compatibility
   767	     * @return newly created ISOMsg
   768	     */
   769	    protected ISOMsg createMsg () {
   770	        return createISOMsg();
   771	    }
   772	    protected ISOMsg createISOMsg () {
   773	        return packager.createISOMsg ();
   774	    }
   775	
   776	    /**
   777	     * Reads in a message header.
   778	     *
   779	     * @param hLen The Length og the reader to read
   780	     * @return The header bytes that were read in
   781	     * @throws IOException on error
   782	     */
   783	    protected byte[] readHeader(int hLen) throws IOException {
   784	        byte[] header = new byte[hLen];
   785	        serverIn.readFully(header, 0, hLen);
   786	        return header;
   787	    }
   788	    /**
   789	     * Waits and receive an ISOMsg over the TCP/IP session
   790	     * @return the Message received
   791	     * @throws IOException
   792	     * @throws ISOException
   793	     */
   794	    public ISOMsg receive() throws IOException, ISOException {
   795	        var jfr = new ChannelEvent.Receive();
   796	        jfr.begin();
   797	
   798	        byte[] b=null;
   799	        byte[] header=null;
   800	        LogEvent evt = new LogEvent (this, "receive").withTraceId(getSocketUUID());
   801	        ISOMsg m = createMsg ();  // call createMsg instead of createISOMsg for backward compatibility
   802	
   803	        m.setSource (this);
   804	        try {
   805	            if (!isConnected())
   806	                throw new IOException ("unconnected ISOChannel");
   807	
   808	            serverInLock.lock();
   809	            try {
   810	                int len  = getMessageLength();
   811	                if (expectKeepAlive) {
   812	                    while (len == 0) {
   813	                        //If zero length, this is a keep alive msg
   814	                        len  = getMessageLength();
   815	                    }
   816	                }
   817	                int hLen = getHeaderLength();
   818	
   819	                if (len == -1) {
   820	                    if (hLen > 0) {
   821	                        header = readHeader(hLen);
   822	                    }
   823	                    b = streamReceive();
   824	                }
   825	                else if (len > 0 && len <= getMaxPacketLength()) {
   826	                    if (hLen > 0) {
   827	                        // ignore message header (TPDU)
   828	                        // Note header length is not necessarily equal to hLen (see VAPChannel)
   829	                        header = readHeader(hLen);
   830	                        len -= header.length;
   831	                    }
   832	                    b = new byte[len];
   833	                    getMessage (b, 0, len);
   834	                    getMessageTrailer(m);
   835	                }
   836	                else
   837	                    throw new ISOException(
   838	                        "receive length " +len + " seems strange - maxPacketLength = " + getMaxPacketLength());
   839	            } finally {
   840	                serverInLock.unlock();
   841	            }
   842	            m.setPackager (getDynamicPackager(header, b));
   843	            m.setHeader (getDynamicHeader(header));
   844	            if (b.length > 0 && !shouldIgnore (header))  // Ignore NULL messages
   845	                unpack (m, b);
   846	            m.setDirection(ISOMsg.INCOMING);
   847	            evt.addMessage (m);
   848	            applyTags (evt, m);
   849	            m = applyIncomingFilters (m, header, b, evt);
   850	            m.setDirection(ISOMsg.INCOMING);
   851	            cnt[RX]++;
   852	            incrementMsgInCounter(m);
   853	            setChanged();
   854	            notifyObservers(m);
   855	        } catch (ISOException e) {
   856	            evt.addMessage (e);
   857	            if (header != null) {
   858	                evt.addMessage ("--- header ---");
   859	                evt.addMessage (ISOUtil.hexdump (header));
   860	            }

