 28	/**
 29	 * Allow runtime binding of jPOS's components (ISOChannels, Logger, MUXes, etc)
 30	 *
 31	 * @author <a href="mailto:apr@cs.com.uy">Alejandro P. Revilla</a>
 32	 * @version $Revision$ $Date$
 33	 */
 34	public class NameRegistrar implements Loggeable {
 35	    private static final NameRegistrar instance = new NameRegistrar();
 36	    private static final TSpace<String, Object> sp = new TSpace<String,Object>();
 37	
 38	    public static class NotFoundException extends Exception {
 39	        private static final long serialVersionUID = 8744022794646381475L;
 40	
 41	        public NotFoundException() {
 42	            super();
 43	        }
 44	
 45	        public NotFoundException(String detail) {
 46	            super(detail);
 47	        }
 48	    }
 49	
 50	    private NameRegistrar() {
 51	        super();
 52	    }
 53	
 54	    public static TSpace<String, Object> getSpace() {
 55	        return sp;
 56	    }
 57	
 58	    /**
 59	     * @return a copy of the NameRegistrar's entries as a Map
 60	     */
 61	    public static Map<String,Object> getAsMap() {
 62	        Map<String,Object> map = new HashMap<String,Object>();
 63	        for (String k : sp.getKeySet()) {
 64	            Object v  = sp.rdp(k);
 65	            if (v != null)
 66	                map.put(k,v);
 67	        }
 68	        return map;
 69	    }
 70	
 71	    /**
 72	     * @return singleton instance
 73	     */
 74	    public static NameRegistrar getInstance() {
 75	        return instance;
 76	    }
 77	
 78	    /**
 79	     * register object
 80	     *
 81	     * @param key
 82	     *            - key with which the specified value is to be associated.
 83	     * @param value
 84	     *            - value to be associated with the specified key
 85	     */
 86	    public static void register(String key, Object value) {
 87	        sp.put(key, value);
 88	    }
 89	
 90	    /**
 91	     * @param key
 92	     *            key whose mapping is to be removed from registrar.
 93	     */
 94	    public static void unregister(String key) {
 95	        SpaceUtil.wipe(sp, key);
 96	    }
 97	
 98	    /**
 99	     * Get a value from the registry.
100	     *
101	     * @param <T> desired type of entry value.
102	     * @param key the key whose associated value is to be returned.
103	     * @return a value
104	     * @throws NotFoundException if key not present in registrar
105	     */
106	    public static <T> T get(String key) throws NotFoundException {
107	        @SuppressWarnings("unchecked")
108	        T obj = (T) sp.rdp(key);
109	        if (obj == null) {
110	            throw new NotFoundException(key);
111	        }
112	        return obj;
113	    }
114	
115	    /**
116	     * Get a value from the registry - wait for it specified time.
117	     *
118	     * @param <T> desired type of value.
119	     * @param key the key whose associated value is to be returned.
120	     * @param timeout the maximum waiting time (in miliseconds) for
121	     * the appearance of value in the registry.
122	     * @return a value or {@code null} if it does not exist
123	     */
124	    public static <T> T get(String key, long timeout) {
125	        return (T) sp.rd(key, timeout);
126	    }
127	
128	    /**
129	     * Get a value from the registry - without casting {@code NotFoundException}.
130	     *
131	     * @param <T> desired type of value.
132	     * @param key the key whose associated value is to be returned.
133	     * @return a value or {@code null} if it does not exist
134	     */
135	    public static <T> T getIfExists(String key) {
136	        @SuppressWarnings("unchecked")
137	        T obj = (T) sp.rdp(key);
138	        return obj;
139	    }
140	
141	    public void dump(PrintStream p, String indent) {
142	        dump(p, indent, false);
143	    }
144	
145	    public void dump(PrintStream p, String indent, boolean detail) {
146	        String inner = indent + "  ";
147	        p.println(indent + "name-registrar:");
148	        for (String key : sp.getKeySet()) {
149	            Object obj = sp.rdp(key);
150	            String objectClassName = obj == null ? "<NULL>" : obj.getClass().getName();
151	            p.println(inner + key + ": " + objectClassName);
152	            if (detail && obj instanceof Loggeable) {
153	                try {
154	                    ((Loggeable) obj).dump(p, inner + "  ");
155	                } catch (Exception e) {         // typically a NPE may be thrown from badly-initialized objects
156	                    p.println(e.getMessage());
157	                }
158	            }
159	        }
160	    }
161	}

