 28	import java.util.ConcurrentModificationException;
 29	import java.util.Iterator;
 30	import java.util.List;
 31	
 32	/**
 33	 * Peer class Logger forwards LogEvents generated by LogSources 
 34	 * to LogListeners.
 35	 * <br>
 36	 * This little <a href="/doc/LoggerGuide.html">tutorial</a>
 37	 * give you additional information on how to extend the jPOS's
 38	 * Logger subsystem.
 39	 *
 40	 * @author apr@cs.com.uy
 41	 * @version $Id$
 42	 * @see LogEvent
 43	 * @see LogSource
 44	 * @see LogListener
 45	 * @see Loggeable
 46	 * @see SimpleLogListener
 47	 * @see RotateLogListener
 48	 */
 49	@SuppressWarnings("unchecked")
 50	public class Logger implements LogProducer,Configurable
 51	{
 52	    Configuration cfg;
 53	    String name;
 54	    List<LogListener> listeners;
 55	    public static final String NRPREFIX = "logger.";
 56	
 57	    public Logger () {
 58	        super();
 59	        listeners = Collections.synchronizedList(new ArrayList<>());
 60	        name = "";
 61	    }
 62	
 63	    public Configuration getConfiguration()
 64	    {
 65	        return cfg;
 66	    }
 67	
 68	    @Override
 69	    public void setConfiguration(Configuration cfg) throws ConfigurationException
 70	    {
 71	        this.cfg = cfg;
 72	    }
 73	
 74	    public void addListener (LogListener l) {
 75	        listeners.add(l);
 76	    }
 77	    public void removeListener (LogListener l) {
 78	        listeners.remove(l);
 79	    }
 80	    public void removeAllListeners () {
 81	        for (Object l : listeners) {
 82	            if (l instanceof Destroyable) {
 83	                ((Destroyable) l).destroy();
 84	            }
 85	        }
 86	        listeners.clear ();
 87	    }
 88	    public static void log (LogEvent evt) {
 89	        Logger l = null;
 90	        LogSource source = evt.getSource();
 91	        if (source != null)
 92	            l = source.getLogger();
 93	        if (l == null && !evt.isHonorSourceLogger()) {
 94	            l = getLogger(Q2.LOGGER_NAME);
 95	        }
 96	        if (l != null && l.hasListeners ()) {
 97	            Iterator<LogListener> i = l.listeners.iterator();
 98	            while (i.hasNext() && evt != null) {
 99	                try {
100	                    evt = i.next().log(evt);
101	                } catch (ConcurrentModificationException e) {
102	                    break;
103	                } catch (Throwable t) {
104	                    evt.addMessage (t);
105	                }
106	            }
107	        }
108	    }
109	    /**
110	     * associates this Logger with a name using NameRegistrar
111	     * @param name name to register
112	     * @see NameRegistrar
113	     */
114	    public void setName (String name) {
115	        this.name = name;
116	        NameRegistrar.register (NRPREFIX+name, this);
117	    }
118	    /**
119	     * destroy logger
120	     */
121	    public void destroy () {
122	        NameRegistrar.unregister (NRPREFIX+name);
123	        removeAllListeners ();
124	    }
125	    /**
126	     * @return logger instance with given name. Creates one if necessary
127	     * @see NameRegistrar
128	     */
129	    public synchronized static Logger getLogger (String name) {
130	        Logger l;
131	        try {
132	            l = NameRegistrar.get (NRPREFIX+name);
133	        } catch (NameRegistrar.NotFoundException e) {
134	            l = new Logger();
135	            l.setName (name);
136	        }
137	        return l;
138	    }
139	    /**
140	     * @return this logger's name ("" if no name was set)
141	     */
142	    public String getName() {
143	        return this.name;
144	    }
145	    /**
146	     * Used by heavy used methods to avoid LogEvent creation 
147	     * @return true if Logger has associated LogListsners
148	     */
149	    public boolean hasListeners() {
150	        return !listeners.isEmpty();
151	    }
152	}

