19	package org.jpos.metrics;
20	
21	import com.sun.net.httpserver.HttpServer;
22	import org.jdom2.Element;
23	import org.jpos.core.ConfigurationException;
24	import org.jpos.core.annotation.Config;
25	import org.jpos.q2.QBeanSupport;
26	
27	import java.io.IOException;
28	import java.io.OutputStream;
29	import java.net.InetSocketAddress;
30	
31	public class PrometheusService extends QBeanSupport {
32	    @Config("port")
33	    private int port;
34	    @Config("path")
35	    private String path;
36	    @Config("status-path")
37	    private String statusPath;
38	    private HttpServer server;
39	
40	    @Override
41	    protected void initService() throws ConfigurationException {
42	        try {
43	            final var registry =  getServer().getPrometheusMeterRegistry();
44	            server = HttpServer.create(new InetSocketAddress(port), 0);
45	            server.createContext(path, httpExchange -> {
46	                String response = registry.scrape();
47	                httpExchange.getResponseHeaders().add("Content-Type", "text/plain; version=0.0.4");
48	                httpExchange.sendResponseHeaders(200, response.getBytes().length);
49	                try (OutputStream os = httpExchange.getResponseBody()) {
50	                    os.write(response.getBytes());
51	                }
52	            });
53	            if (statusPath != null) {
54	                server.createContext(statusPath, httpExchange -> {
55	                    String response = getServer().running() ? "running\n" : "stopping\n";
56	                    httpExchange.getResponseHeaders().add("Content-Type", "text/plain");
57	                    httpExchange.sendResponseHeaders(200, response.getBytes().length);
58	                    try (OutputStream os = httpExchange.getResponseBody()) {
59	                        os.write(response.getBytes());
60	                    }
61	                });
62	            }
63	            Thread.ofVirtual().start(server::start);
64	        } catch (IOException e) {
65	            getLog().warn(e);
66	            throw new RuntimeException(e);
67	        }
68	    }
69	
70	    @Override
71	    protected void stopService() {
72	        server.stop(2);
73	    }
74	
75	    public static Element createDescriptor (int port, String path, String statusPath) {
76	        return new Element("prometheus")
77	          .addContent(createProperty ("port", Integer.toString(port)))
78	          .addContent (createProperty ("path", path))
79	          .addContent (createProperty ("status-path", statusPath));
80	
81	    }
82	    private static Element createProperty (String name, String value) {
83	        return new Element ("property")
84	          .setAttribute("name", name)
85	          .setAttribute("value", value);
86	    }
87	}

