    45	@SuppressWarnings("unchecked")
    46	public class JDBMSpace<K,V> extends TimerTask implements Space<K,V>, PersistentSpace {
    47	    protected HTree htree;
    48	    protected RecordManager recman;
    49	    protected static final Serializer refSerializer = new Ref ();
    50	    protected static final Map<String,Space> spaceRegistrar = new HashMap<String,Space> ();
