    61	    protected JDBMSpace (String name, String filename) {
    62	        super();
    63	        this.name = name;
    64	        try {
    65	            Properties props = new Properties();
    66	            props.put (RecordManagerOptions.CACHE_SIZE, "512");
    67	            recman = RecordManagerFactory.createRecordManager (filename, props);
    68	            long recid = recman.getNamedObject ("space");
    69	            if (recid != 0) {
    70	                htree = HTree.load (recman, recid);
    71	            } else {
    72	                htree = HTree.createInstance (recman);
    73	                recman.setNamedObject ("space", htree.getRecid());
    74	            }
    75	            recman.commit ();
    76	        } catch (IOException e) {
    77	            throw new SpaceError (e);
    78	        }
